      "replace": "    total: int = pydantic.Field()
    @pydantic.root_validator(pre=True)
    def _set_total(cls, values: dict) -> dict:
        """If total is omitted, compute it as input + output.

        This maintains backward compatibility where callers only supply
        ``input`` and ``output``. ``total`` will be set to the sum of those
        fields when not explicitly provided.
        """
        if values.get("total") is None:
            input_val = values.get("input", 0) or 0
            output_val = values.get("output", 0) or 0
            values["total"] = input_val + output_val
        return values"
